function renders(keystrokes, subscribers) {
  // global shape: every keystroke re-renders every subscriber
  const global = keystrokes * subscribers;
  // local shape: every keystroke re-renders only the search box (1 component)
  const local = keystrokes * 1;
  return { global, local, wastedAvoided: global - local };
}
const r = renders(20, 12);
console.log(`global=${r.global} local=${r.local} wastedAvoided=${r.wastedAvoided}`);
